/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// UI Builder class for the cover note report
/// </summary>
class METOrderShipmentBundlingReportUIBuilder extends SysOperationAutomaticUIBuilder
{
    METOrderShipmentBundlingReportContract dataContract;
    DialogField dialogLoadId;

}

Method.Source:
/// <summary>
/// Builds contract.
/// </summary>
public void build()
{ 
    dataContract = this.dataContractObject() as METOrderShipmentBundlingReportContract;

    dialogLoadId = this.addDialogField(methodStr(METOrderShipmentBundlingReportContract, parmLoadId), dataContract);
}

/// <summary>
/// Post run method.
/// </summary>
public void postRun()
{
    super();

    if (dataContract.parmIsReprint())
    {
        dialogLoadId.visible(false); // Hide this in everycase
    }

    if (dataContract.parmIsMultiThreadedJob())
    {
        dialogLoadId.visible(false);
    }
    else
    {
        controller.parmDisplayQueryFilter(false);
    }
}
